import {fieldPresets,catalogPresets,generateFieldTask,defaultVariable} from './field-generator.js';
import {highlightCode} from './abap-highlight.js';
import {codeOnlyHTML} from './code-tools.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let deps={},task='f4',values={ddic:'BKPF-BUKRS',screenType:'selection',program:'ZFIELD_HELP',variable:'PA_BUKRS',screen:'0100',helpMode:'query',enter:true,required:true,catalogTable:'BKPF'},columns=catalogPresets.BKPF.map(([field,label,key])=>({field,label,key:!!key,edit:false,hotspot:false,selected:true})),result=null,index=0,dirty=false;
const tasks=[['f4','F4 + Enter','값 선택 · 직접 입력 검사'],['enter','Enter 검증','필수값 · 존재 검사'],['listbox','리스트박스','코드 + 텍스트 목록'],['fcat','MAKE_FCAT','테이블 → ALV 열 구성']];
export function builderPage(){return `<section class="field-builder"><header class="builder-head"><h1>필드 넣고, 코드 만들기</h1><p>F4 · Enter · 리스트박스 · MAKE_FCAT</p></header><nav class="builder-tasks" aria-label="만들 작업">${tasks.map(([id,title,desc])=>`<button data-builder-task="${id}" aria-pressed="${task===id}"><strong>${title}</strong><span>${desc}</span></button>`).join('')}</nav><div class="builder-example-links"><strong>완성 코드 예제도 함께 보기</strong><a href="#docs/code/alv/fcat">MAKE_FCAT · 속성별 7개</a><a href="#docs/code/alv/header">CREATE_TOP · 상단 출력</a><a href="#docs/code/read/basic">READ · 12개</a><a href="#docs/code/loop/basic">LOOP · 12개</a><a href="#docs/code/modern/construct">신문법 · 18개</a></div><div class="builder-layout"><form id="field-builder-form"><div id="builder-inputs"></div><p id="builder-error" role="alert"></p><button type="submit" class="builder-generate">코드 만들기 →</button></form><article id="builder-output"></article></div></section>`;}
function fieldInputs(){const preset=fieldPresets.find(p=>p.id===values.ddic.toUpperCase()),dyn=values.screenType==='dynpro';
 return `<label class="builder-label">어떤 DDIC 필드인가요?<input name="ddic" id="builder-ddic" list="standard-fields" value="${esc(values.ddic)}" placeholder="BKPF-BUKRS" required autocomplete="off"><datalist id="standard-fields">${fieldPresets.map(p=>`<option value="${p.id}">${esc(p.label)}</option>`).join('')}</datalist></label><div class="builder-presets">${['BKPF-BUKRS','BKPF-BELNR','BKPF-BLART','BSEG-HKONT'].map(id=>`<button type="button" data-builder-preset="${id}">${id}</button>`).join('')}</div><details class="builder-presets-all"><summary>표준 필드 ${fieldPresets.length}개에서 고르기</summary><div class="builder-presets">${fieldPresets.map(p=>`<button type="button" data-builder-preset="${p.id}">${esc(p.label)} · ${p.id}</button>`).join('')}</div></details>${preset?`<p class="builder-contract"><strong>${esc(preset.label)}</strong> · 검증: ${preset.table}-${preset.key}${preset.context.length?`<br>함께 입력: ${preset.context.map(c=>esc(c[2])+' ('+(dyn?'GV_':'PA_')+c[0]+')').join(', ')}`:''}</p>`:`<div class="builder-custom"><p>등록되지 않은 필드입니다. SE11의 확인 테이블과 키를 입력하세요.</p><label>검증 테이블<input name="checkTable" value="${esc(values.checkTable||'')}" placeholder="예: ZMASTER" required></label><label>검증 키 필드<input name="checkKey" value="${esc(values.checkKey||'')}" placeholder="예: CODE" required></label><label>같은 테이블의 텍스트 필드 · 선택<input name="textField" value="${esc(values.textField||'')}" placeholder="예: TEXT"></label><label>입력 변환<select name="conversion">${['없음','ALPHA','MATN1'].map(v=>`<option ${values.conversion===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`}<div class="builder-pair"><label>화면 종류<select name="screenType" id="builder-screen-type"><option value="selection" ${dyn?'':'selected'}>조회조건</option><option value="dynpro" ${dyn?'selected':''}>Dynpro</option></select></label><label>화면 변수<input name="variable" value="${esc(values.variable)}" required></label></div>${task==='f4'?`<label>F4 후보 방식<select name="helpMode"><option value="query" ${values.helpMode==='query'?'selected':''}>조건 조회 · 후보 직접 구성</option><option value="ddic" ${values.helpMode==='ddic'?'selected':''}>DDIC에 연결된 표준 검색도움</option></select></label><label class="builder-check"><input type="checkbox" name="enter" ${values.enter?'checked':''}>직접 입력 후 Enter 검증도 생성</label>`:''}<label class="builder-check"><input type="checkbox" name="required" ${values.required?'checked':''}>필수 입력</label>${dyn?`<label>화면번호<input name="screen" value="${esc(values.screen)}" pattern="[0-9]{4}"></label>`:''}<details class="builder-advanced"><summary>프로그램명</summary><label>SE38 프로그램<input name="program" value="${esc(values.program)}" required></label></details>`;
}
function catalogInputs(){return `<label class="builder-label">어떤 테이블인가요?<input name="catalogTable" id="builder-catalog-table" value="${esc(values.catalogTable)}" list="catalog-tables" required><datalist id="catalog-tables">${Object.keys(catalogPresets).map(id=>`<option>${id}</option>`).join('')}</datalist></label><p class="builder-contract">기존 ALV의 GT_DATA · GCL_GRID에 붙일 MAKE_FCAT을 만듭니다.</p><div class="catalog-fields"><div class="catalog-field-labels"><span>표시 / 필드 / 열 제목</span><span>키 · 편집 · 링크</span></div>${columns.map((r,i)=>`<div class="catalog-field" data-catalog-row="${i}"><input type="checkbox" data-col="selected" ${r.selected?'checked':''} aria-label="${esc(r.field)} 표시"><input data-col="field" value="${esc(r.field)}" aria-label="필드명"><input data-col="label" value="${esc(r.label)}" maxlength="40" aria-label="열 제목"><label title="키"><input type="checkbox" data-col="key" ${r.key?'checked':''}><span>키</span></label><label title="편집"><input type="checkbox" data-col="edit" ${r.edit?'checked':''}><span>편집</span></label><label title="핫스폿"><input type="checkbox" data-col="hotspot" ${r.hotspot?'checked':''}><span>링크</span></label><button type="button" data-column-remove="${i}" aria-label="${esc(r.field)} 삭제">×</button></div>`).join('')}</div><button type="button" class="builder-add" data-column-add>+ 필드 추가</button>${columns.some(c=>['WRBTR','DMBTR'].includes(c.field.toUpperCase())&&c.selected)?`<label>WRBTR 통화 참조 · GT_DATA의 필드명<input name="currencyField" value="${esc(values.currencyField||'')}" placeholder="WAERS"></label><label>DMBTR 현지통화 참조 · GT_DATA의 필드명<input name="localCurrencyField" value="${esc(values.localCurrencyField||'')}" placeholder="HWAER"></label>`:''}<details class="builder-advanced"><summary>파일 이름</summary><label>프로그램<input name="program" value="${esc(values.program)}"></label></details>`;}
function capture(){const form=document.querySelector('#field-builder-form');if(!form)return;const data=Object.fromEntries(new FormData(form));values={...values,...data};if(task!=='fcat'){values.enter=task==='f4'?new FormData(form).has('enter'):true;values.required=new FormData(form).has('required');}document.querySelectorAll('[data-catalog-row]').forEach(row=>{const r=columns[Number(row.dataset.catalogRow)];row.querySelectorAll('[data-col]').forEach(input=>r[input.dataset.col]=input.type==='checkbox'?input.checked:input.value);});}
function renderInputs(){const host=document.querySelector('#builder-inputs');if(host)host.innerHTML=task==='fcat'?catalogInputs():fieldInputs();}
export function renderBuilder(){renderInputs();renderOutput();}
function renderOutput(){const host=document.querySelector('#builder-output');if(!host)return;if(!result){host.innerHTML='<div class="builder-empty"><span>{ }</span><h2>필요한 코드만 만드세요.</h2><p>필드와 작업을 선택하면 선언·이벤트·FORM을 연결합니다.</p></div>';return;}const f=result.files[index];host.innerHTML=`<header class="builder-result-head"><h2>${esc(result.title)}</h2><div class="builder-output-actions"><button data-builder-copy ${dirty?'disabled':''}>현재 코드 복사</button><button data-builder-zip ${dirty?'disabled':''}>전체 파일 ZIP</button><button data-builder-html ${dirty?'disabled':''}>HTML 저장</button></div>${dirty?'<p class="builder-stale">설정이 바뀌었습니다. 코드 만들기를 다시 눌러주세요.</p>':''}</header><nav class="builder-files" aria-label="생성한 파일">${result.files.map((f,i)=>`<button data-builder-file="${i}" class="${i===index?'active':''}">${esc(f.name.includes('_complete.')?'전체 프로그램':f.where.split(' · ')[0])}</button>`).join('')}</nav><div class="builder-code-location">${esc(f.where)} · ${f.code.split('\n').length}줄</div><pre class="abap-code builder-code" tabindex="0"><code>${highlightCode(f.code)}</code></pre><details class="builder-notes" open><summary>붙여 넣을 위치 · 준비할 객체</summary><ul>${result.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><a href="${task==='fcat'?'https://help.sap.com/docs/SUPPORT_CONTENT/abap/3353523898.html':task==='listbox'?'https://help.sap.com/docs/SUPPORT_CONTENT/abap/3353524243.html':'https://help.sap.com/docs/SAP_NETWEAVER_750/f68e489816e043f1add91d69a6842931/4a439fcb5a503f04e10000000a421937.html'}" target="_blank" rel="noopener noreferrer">SAP ${task==='fcat'?'필드 카탈로그':task==='listbox'?'리스트박스':'입력 도움말'} 문서 ↗</a></details>`;}
function invalidate(){if(!result)return;dirty=true;renderOutput();}
export function bindBuilder(d){deps=d;
 document.addEventListener('submit',e=>{if(e.target.id!=='field-builder-form')return;e.preventDefault();capture();try{result=generateFieldTask({...values,task,columns:columns.filter(c=>c.selected)});index=task==='fcat'?1:0;dirty=false;document.querySelector('#builder-error').textContent='';renderOutput();}catch(err){document.querySelector('#builder-error').textContent=err.message;invalidate();}});
 document.addEventListener('input',e=>{if(e.target.closest('#field-builder-form'))invalidate();});
 document.addEventListener('change',e=>{if(!e.target.closest('#field-builder-form'))return;capture();if(e.target.id==='builder-ddic'||e.target.id==='builder-screen-type'){const field=values.ddic.toUpperCase().split('-')[1]||'VALUE';values.ddic=values.ddic.toUpperCase();values.variable=defaultVariable(values.ddic,values.screenType==='dynpro');renderInputs();}if(['field','selected'].includes(e.target.dataset?.col))renderInputs();if(e.target.id==='builder-catalog-table'){const table=values.catalogTable.toUpperCase();values.catalogTable=table;columns=(catalogPresets[table]||[]).map(([field,label,key])=>({field,label,key:!!key,edit:false,hotspot:false,selected:true}));renderInputs();}invalidate();});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.builderTask){capture();task=b.dataset.builderTask;result=null;dirty=false;index=0;document.querySelector('#main').innerHTML=builderPage();renderBuilder();return;}
  if(b.dataset.builderPreset){capture();values.ddic=b.dataset.builderPreset;values.variable=defaultVariable(values.ddic,values.screenType==='dynpro');renderInputs();invalidate();return;}
  if(b.hasAttribute('data-column-add')){capture();columns.push({field:'',label:'',selected:true});renderInputs();invalidate();return;}
  if(b.dataset.columnRemove!==undefined){capture();columns.splice(Number(b.dataset.columnRemove),1);renderInputs();invalidate();return;}
  if(b.dataset.builderFile!==undefined){index=Number(b.dataset.builderFile);renderOutput();return;}
  if(!result||dirty)return;
  if(b.hasAttribute('data-builder-copy'))deps.copy(result.files[index].code,result.title+' · '+result.files[index].where);
  if(b.hasAttribute('data-builder-html')){const f=result.files[index];deps.download(f.name.replace(/\.abap$/,'.html'),codeOnlyHTML(result.title,f.code),'text/html;charset=utf-8');}
  if(b.hasAttribute('data-builder-zip'))deps.download(values.program.toLowerCase()+'-'+task+'.zip',deps.zip([...result.files.map(f=>({name:f.name,code:f.code})),{name:'00_README.txt',code:result.notes.join('\n\n')}]),'application/zip');
 });
}

export function configureBuilder(kind,ddic,table){task=kind||'f4';if(ddic)values.ddic=ddic;values.variable=defaultVariable(values.ddic,values.screenType==='dynpro');if(table){values.catalogTable=table;columns=(catalogPresets[table]||[]).map(([field,label,key])=>({field,label,key:!!key,selected:true}));}result=null;dirty=false;}
